#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# One-off setup for Releases (#57, #59): the Homebrew tap, the crates.io token and the crate's
# owners, and the GitHub secrets the release workflow reads. Re-run it after the first Release
# (0.1.0) is on crates.io, and when the tap token nears its yearly expiry: each run works out what's
# done from read-only checks and does only the rest. `--status` just prints that.
# No value is written to disk: the tokens go straight into GitHub secrets.

# ── Read-only checks ──────────────────────────────────────────────────────

# secret_set_at NAME: when the Actions secret NAME was last set on $REPO (ISO 8601), or nothing.
secret_set_at() {
  gh secret list -R "$REPO" --json name,updatedAt --jq ".[] | select(.name == \"$1\") | .updatedAt"
}

# crates_io PATH: crates.io's API answer for PATH, or nothing (not there yet, or unreachable).
crates_io() {
  curl -fsS -A "$USER_AGENT" "https://crates.io/api/v1/$1" 2>/dev/null || true
}

# crate_published_at: when $CRATE first reached crates.io, or nothing if it isn't there yet.
crate_published_at() {
  crates_io "crates/$CRATE" | jq -r '.crate.created_at // empty'
}

team_owns_crate() {
  crates_io "crates/$CRATE/owner_team" |
    jq -e --arg t "github:$ORG_ID:$TEAM" '[.teams[]?.login] | index($t)' >/dev/null
}

# image_visibility: public, private or internal; none (no image pushed yet); or unknown (this gh
# login can't tell).
image_visibility() {
  local out
  if out=$(gh api "orgs/$ORG/packages/container/$CRATE" --jq .visibility 2>&1); then
    printf '%s' "$out"
  elif [[ "$out" == *"Package not found"* ]]; then
    printf none
  else
    printf unknown
  fi
}

# older_than_days ISO DAYS: whether ISO (UTC) is more than DAYS days ago. BSD and GNU date.
older_than_days() {
  local cutoff
  cutoff=$(date -u -v-"$2"d +%Y-%m-%dT%H:%M:%S 2>/dev/null || date -u -d "$2 days ago" +%Y-%m-%dT%H:%M:%S)
  [[ "${1:0:19}" < "$cutoff" ]]
}

# The state every stage is decided from, gathered once.
gather() {
  TAP_EXISTS=no TEAM_EXISTS=no TEAM_OWNS=no
  if gh repo view "$TAP" >/dev/null 2>&1; then TAP_EXISTS=yes; fi
  TAP_TOKEN_AT=$(secret_set_at HOMEBREW_TAP_TOKEN)
  CRATE_TOKEN_AT=$(secret_set_at CARGO_REGISTRY_TOKEN)
  PUBLISHED_AT=$(crate_published_at)
  if gh api "orgs/$ORG/teams/$TEAM" >/dev/null 2>&1; then TEAM_EXISTS=yes; fi
  if team_owns_crate; then TEAM_OWNS=yes; fi
  IMAGE_VISIBILITY=$(image_visibility)
}

# ── What each stage is for, and whether it still needs doing ──────────────

label() {
  case $1 in
    tap) echo "the Homebrew tap $TAP exists" ;;
    tap_token) echo "HOMEBREW_TAP_TOKEN is set and under 330 days old" ;;
    first_token) echo "CARGO_REGISTRY_TOKEN may publish $CRATE for the first time, and is under 28 days old" ;;
    update_token) echo "CARGO_REGISTRY_TOKEN may only publish updates (once $CRATE is on crates.io)" ;;
    team) echo "the $ORG team $TEAM exists" ;;
    org_access) echo "crates.io may see $ORG's teams" ;;
    team_owner) echo "the team $TEAM owns $CRATE on crates.io" ;;
    image) echo "the image ghcr.io/$ORG_ID/$CRATE is public (once a Release has pushed it)" ;;
  esac
}

needs_tap() { [[ $TAP_EXISTS == no ]]; }
needs_tap_token() { [[ -z $TAP_TOKEN_AT ]] || older_than_days "$TAP_TOKEN_AT" 330; }
# The first-publish token lasts 30 days: one set longer ago than that may have run out.
needs_first_token() { [[ -z $PUBLISHED_AT ]] && { [[ -z $CRATE_TOKEN_AT ]] || older_than_days "$CRATE_TOKEN_AT" 28; }; }
# The update-only token is the one set after the crate was first published.
needs_update_token() { [[ -n $PUBLISHED_AT && ( -z $CRATE_TOKEN_AT || ! "${CRATE_TOKEN_AT:0:19}" > "${PUBLISHED_AT:0:19}" ) ]]; }
needs_team() { [[ -n $PUBLISHED_AT && $TEAM_EXISTS == no ]]; }
needs_team_owner() { [[ -n $PUBLISHED_AT && $TEAM_OWNS == no ]]; }
# Done once the team owns the crate, which crates.io only allows with this access.
needs_org_access() { needs_team_owner; }
needs_image() { [[ $IMAGE_VISIBILITY == private || $IMAGE_VISIBILITY == internal || $IMAGE_VISIBILITY == unknown ]]; }

# not_yet STAGE: whether STAGE can't come up yet: the crate's stages wait for 0.1.0, the image's
# for #12.
not_yet() {
  case $1 in
    update_token | team | org_access | team_owner) [[ -z $PUBLISHED_AT ]] ;;
    image) [[ $IMAGE_VISIBILITY == none ]] ;;
    *) false ;;
  esac
}

status() {
  local s
  for s in "${STAGES[@]}"; do
    if "needs_$s"; then printf '  %s○ to do%s  %s\n' "$YELLOW" "$RESET" "$(label "$s")"
    elif not_yet "$s"; then printf '  %s· later%s  %s\n' "$DIM" "$RESET" "$(label "$s")"
    else printf '  %s✓ done%s   %s\n' "$GREEN" "$RESET" "$(label "$s")"; fi
  done
  [[ -n $TAP_TOKEN_AT ]] && note "HOMEBREW_TAP_TOKEN set $TAP_TOKEN_AT: GitHub tokens last a year at most"
  if [[ -n $PUBLISHED_AT ]]; then note "$CRATE first published $PUBLISHED_AT"
  else note "$CRATE isn't on crates.io yet: the crate's owner stages wait for 0.1.0"; fi
  [[ $IMAGE_VISIBILITY == none ]] && note "no image pushed yet (#12)"
  [[ $IMAGE_VISIBILITY == unknown ]] && note "can't see the image's visibility with this gh login (it lacks read:packages)"
  return 0
}

# ── Helpers for the stages ────────────────────────────────────────────────

# ask_token VAR "Prompt": a pasted token into VAR, asking again until something is pasted.
ask_token() {
  while :; do
    ask_secret "$1" "$2"
    [[ -n ${!1} ]] && return 0
    warn "Nothing was pasted. Paste the token, or Ctrl-C to stop and re-run later."
  done
}

# new_crate_token VAR NAME EXPIRATION SCOPES: walk through making a crates.io token for $CRATE,
# into VAR.
new_crate_token() {
  open_url "https://crates.io/settings/tokens/new"
  step "Sign in with GitHub if asked."
  step "Name: $2. Expiration: $3."
  step "Scopes: $4. Crates: $CRATE."
  step "Generate Token, then copy it (crates.io shows it once)."
  ask_token "$1" "Paste the token:"
}

# revoke_crate_token NAME: walk through revoking the crates.io token NAME.
revoke_crate_token() {
  open_url "https://crates.io/settings/tokens"
  step "Revoke '$1'$2."
  pause "Press Enter once it's revoked."
}

# ── Stages ────────────────────────────────────────────────────────────────

stage_tap() {
  stage "Homebrew tap: create $TAP"
  say "brew install tooobs/tap/tooob reads its formula from a public repo, $TAP."
  say "The release workflow writes the formula there on every Release."
  if ! confirm "Create the public repo $TAP now?"; then
    SKIPPED+=("create the public repo $TAP")
  elif gh repo create "$TAP" --public --add-readme --description "Homebrew formula for tooob" >/dev/null; then
    TAP_EXISTS=yes
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$TAP"
  else
    SKIPPED+=("create the public repo $TAP (gh repo create failed; see above)")
  fi
}

stage_tap_token() {
  stage "Homebrew tap: a token that can write to it"
  if [[ $TAP_EXISTS == no ]]; then
    note "There's no $TAP yet, so no token can be scoped to it. Re-run once it exists."
    SKIPPED+=("HOMEBREW_TAP_TOKEN (after $TAP exists)")
    return
  fi
  [[ -n $TAP_TOKEN_AT ]] && warn "HOMEBREW_TAP_TOKEN was set $TAP_TOKEN_AT: replace it before it expires."
  say "The release workflow pushes the formula with a token that can write to $TAP and nothing else."
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Token name: tooob releases: homebrew-tap."
  step "Expiration: Custom, a year from today (or the longest $ORG allows)."
  step "Resource owner: $ORG."
  step "Repository access: Only select repositories → homebrew-tap."
  step "Permissions → Repository permissions → Contents: Read and write."
  step "Generate token, then copy it (starts github_pat_)."
  note "If $ORG asks for approval, approve it: https://github.com/organizations/$ORG/settings/personal-access-token-requests"
  ask_token TAP_TOKEN "Paste the token:"
  set_secret HOMEBREW_TAP_TOKEN "$TAP_TOKEN"
  note "Put a reminder in your calendar a few days before it expires, then re-run this wizard."
}

stage_first_token() {
  stage "crates.io: a token for the first publish"
  [[ -n $CRATE_TOKEN_AT ]] && warn "CARGO_REGISTRY_TOKEN was set $CRATE_TOKEN_AT and may have run out."
  say "The first Release creates the crate $CRATE on crates.io, which takes a token that may"
  say "publish a new crate. After 0.1.0, re-run this wizard to swap it for one that can't."
  new_crate_token CRATE_TOKEN "tooob releases: first publish" "30 days" "publish-new and publish-update"
  set_secret CARGO_REGISTRY_TOKEN "$CRATE_TOKEN"
}

stage_update_token() {
  stage "crates.io: a token that may only publish updates"
  say "$CRATE is on crates.io, so the release workflow only needs to publish new Releases of it."
  new_crate_token CRATE_TOKEN "tooob releases" "none (it can only publish updates to $CRATE)" "publish-update only"
  set_secret CARGO_REGISTRY_TOKEN "$CRATE_TOKEN"
  revoke_crate_token "tooob releases: first publish" ", if it's there"
}

stage_team() {
  stage "GitHub: the team $TEAM"
  say "The crate is owned by a team as well as by you, so it doesn't hang on one account."
  open_url "https://github.com/orgs/$ORG/new-team"
  step "Team name: $TEAM. Visibility: Visible (crates.io can't see secret teams)."
  step "Create team. You're added as its maintainer; add anyone else who may publish."
  pause "Press Enter once the team exists."
}

stage_org_access() {
  stage "GitHub: let crates.io see $ORG's teams"
  say "crates.io checks team membership through its GitHub app, which needs access to $ORG."
  open_url "https://github.com/settings/applications"
  step "Authorized OAuth Apps → crates.io."
  step "Organization access → $ORG → Grant (or Request, then approve it as an admin)."
  pause "Press Enter once crates.io has access to $ORG."
}

stage_team_owner() {
  stage "crates.io: make $TEAM an owner of $CRATE"
  say "Adding an owner takes a token with the change-owners scope. It's used once and not kept."
  new_crate_token OWNER_TOKEN "tooob: add team owner" "1 day" "change-owners"
  # Through the environment, not --token, so the token isn't on cargo's command line.
  if CARGO_REGISTRY_TOKEN="$OWNER_TOKEN" cargo owner --add "github:$ORG_ID:$TEAM" "$CRATE"; then
    printf '  %s✓ %s owns %s%s\n' "$GREEN" "$TEAM" "$CRATE" "$RESET"
  else
    SKIPPED+=("cargo owner --add github:$ORG_ID:$TEAM $CRATE (it failed; see above)")
  fi
  OWNER_TOKEN=""
  revoke_crate_token "tooob: add team owner" ""
}

stage_image() {
  stage "GHCR: the image is public"
  if [[ $IMAGE_VISIBILITY == unknown ]] && ! confirm "Has a Release pushed the image ghcr.io/$ORG_ID/$CRATE yet (#12)?"; then
    note "Nothing to do until it has: re-run this wizard after the first Release with the image."
    return
  fi
  say "Home-server app stores pull ghcr.io/$ORG_ID/$CRATE without signing in, so it must be public."
  open_url "https://github.com/orgs/$ORG/packages/container/$CRATE/settings"
  step "If that page isn't found: $ORG → Packages → $CRATE → Package settings."
  step "Danger Zone → Change visibility → Public."
  pause "Press Enter once it's public (or if it already was)."
}

run_wizard() {

ORG=Tooobs
ORG_ID=tooobs # how crates.io and GHCR spell it
REPO=$ORG/tooob
TAP=$ORG/homebrew-tap
CRATE=tooob
TEAM=maintainers
USER_AGENT="tooob-release-setup (https://github.com/$REPO)"
STAGES=(tap tap_token first_token update_token team org_access team_owner image)
export GH_REPO=$REPO # set_secret writes here, whatever this clone's remotes are
ENV_FILE=/dev/null   # nothing is read from or written to a .env
cd "$(dirname "$0")"

if ! command -v gh >/dev/null || ! gh auth status >/dev/null 2>&1; then
  echo "release-setup.sh: needs gh, signed in (gh auth login)" >&2
  exit 1
fi
command -v jq >/dev/null || { echo "release-setup.sh: needs jq" >&2; exit 1; }
gather

if [[ ${1:-} == --status ]]; then
  printf '\n%sRelease setup for %s%s\n' "$BOLD" "$REPO" "$RESET"
  status
  exit 0
fi

local todo=() s
for s in "${STAGES[@]}"; do "needs_$s" && todo+=("$s"); done
TOTAL_STAGES=${#todo[@]}
if (( TOTAL_STAGES == 0 )); then
  printf '\nNothing to do: release setup for %s is complete.\n' "$REPO"
  status
  exit 0
fi

banner "Release setup for $REPO"
for s in "${todo[@]}"; do "stage_$s"; done

finish
status
}

run_wizard "$@"; exit
